CREATE TABLE DEFAULT_ACESSO_PESSOAS
	(
	PES_NUMERO NUMBER (18),
	PES_NOME VARCHAR2 (50),
	PES_CPF VARCHAR2 (11),
	PES_OBS VARCHAR2 (30),
	PES_EMAIL VARCHAR2 (50),
	PES_RG VARCHAR2 (15),
	EST_NUMERO NUMBER (10),
	PES_FLAGREENTRADA NUMBER (1),
	PES_MASTER NUMBER (1),
	PES_FOTO VARCHAR2 (100),
	PES_SENHA VARCHAR2 (6),
	PES_RAMAL VARCHAR2 (10),
	PES_CAMPOPERSO1 VARCHAR2 (50),
	PES_CAMPOPERSO2 VARCHAR2 (50),
	PES_CAMPOPERSO3 VARCHAR2 (50),
	PES_CAMPOPERSO4 VARCHAR2 (50),
	PES_CAMPOPERSO5 VARCHAR2 (50),
	PESSIT_NUMERO NUMBER (3),
	PES_DTSITINICIAL DATE,
	PES_DTSITFINAL DATE,
	CRED_PROV VARCHAR2 (20),
	TOK_NUMEROSERIE NUMBER (18),
	REG_NUMERO NUMBER (10),
	RFA_NUMERO NUMBER (10),
	EMP_NUMERO NUMBER (18),
	PES_RECOLHEPROV DATE,
	PES_PIS NUMBER (18)
	)

